css:
[data-theme="dashy-dark"] .section.tinted .card{
  /* La tuile reprend le bouton Dashy : couleur pleine, coins arrondis, halo
     de la couleur sous la tuile. Legerement eclaircie vers le blanc (88 %)
     pour que le texte sombre reste lisible quelle que soit la teinte
     choisie — c'est ce qui evite d'avoir un texte noir sur un rouge. */
  background:color-mix(in srgb, var(--tile-color) 88%, #ffffff);
  color:#1b1c1d;
  border-color:transparent;
  border-radius:8px;
  box-shadow:0 4px 10px color-mix(in srgb, var(--tile-color) 55%, transparent);
  transition:transform .12s ease,box-shadow .12s ease,background .12s ease;
}

[data-theme="dashy-dark"] .section.tinted .card:hover{
  transform:translateY(-2px);
  box-shadow:0 8px 18px color-mix(in srgb, var(--tile-color) 65%, transparent);
}

/* Appui : la tuile s'enfonce et le halo se resserre. C'est ce qui donne
   l'impression d'un bouton, et non d'une simple carte coloree. */
[data-theme="dashy-dark"] .section.tinted .card:active{
  transform:translateY(1px) scale(.985);
  box-shadow:0 2px 5px color-mix(in srgb, var(--tile-color) 45%, transparent);
}

/* Le badge du widget et l'icone doivent suivre le texte sombre de la tuile. */
[data-theme="dashy-dark"] .section.tinted .widget-badge,
[data-theme="dashy-dark"] .section.tinted .widget-time,
[data-theme="dashy-dark"] .section.tinted .card-title{
  color:#1b1c1d;
}

[data-theme="dashy-dark"] .service-icon{
  filter:none !important;
  opacity:1;
}

[data-theme="dashy-dark"] .section-header{
  color:var(--muted);
}

[data-theme="dashy-dark"] .category-icon{
  color:var(--tile-color, var(--accent));
}
